import json
import sys
import os
from datetime import datetime

def parse_date(date_str):
    """Parses YYYYMMDD format into YYYY-MM-DD."""
    if not date_str or not isinstance(date_str, str) or date_str.strip() == "":
        return None
    date_str = date_str.strip()
    try:
        # Handle YYYYMMDD format
        dt = datetime.strptime(date_str, "%Y%m%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        return None

def solve():
    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Find the enforcement reports file in the directory
    reports_filename = None
    for filename in os.listdir(packet_dir):
        if filename.startswith("fda_enforcement_reports"):
            reports_filename = filename
            break

    if not reports_filename:
        return

    reports_path = os.path.join(packet_dir, reports_filename)
    doc_name = os.path.splitext(reports_filename)[0]

    with open(reports_path, 'r') as f:
        reports_data = json.load(f)

    # Create a lookup for recall numbers to their records
    recall_map = {}
    for record in reports_data.get("results", []):
        rn = record.get("recall_number")
        if not rn:
            continue
        if rn not in recall_map:
            recall_map[rn] = []
        recall_map[rn].append(record)

    output = {}

    for pair_str in manifest.get("pairs", []):
        if "::" not in pair_str:
            continue

        rule_id, entity = pair_str.split("::")
        facts_to_find = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        records = recall_map.get(entity, [])

        for fact_name in facts_to_find:
            field_name = ""
            is_date_field = False
            if fact_name == "initiation date":
                field_name = "recall_initiation_date"
                is_date_field = True
            elif fact_name == "classification date":
                field_name = "center_classification_date"
                is_date_field = True
            elif fact_name == "termination date":
                field_name = "termination_date"
                is_date_field = True

            if not field_name:
                pair_result[fact_name] = "ABSENT"
                continue

            # We need to track values and which document they came from
            # to detect conflicts across different records for the same entity.
            found_values_with_docs = []

            for rec in records:
                val = rec.get(field_name)
                # Check if value is present and not an empty string
                if val is not None and str(val).strip() != "":
                    str_val = str(val).strip()
                    if is_date_field:
                        formatted_val = parse_date(str_val)
                        if formatted_val:
                            str_val = formatted_val

                    found_values_with_docs.append((str_val, doc_name))

            # Deduplicate values to check for CONFLICT
            unique_values = sorted(list(set(v[0] for v in found_values_with_docs)))

            if not unique_values:
                pair_result[fact_name] = "ABSENT"
            elif len(unique_values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                # Exactly one unique value found. 
                # Even if multiple records have it, we return the value and the doc.
                # If multiple docs provided the same value, we pick the first one.
                pair_result[fact_name] = {
                    "value": unique_values[0],
                    "document": found_values_with_docs[0][1]
                }

        output[pair_str] = pair_result

    print(json.dumps(output))

if __name__ == "__main__":
